@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task OnCardClicked()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task OnAddToCartClicked()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        var rounded = (int)Math.Round(rating);
        var filled = new string('★', Math.Min(rounded, 5));
        var empty = new string('☆', 5 - Math.Min(rounded, 5));
        return filled + empty;
    }
}

@page "/catalog"
@using sv_b0a32cdef2974757a41a7b12f291b7c2.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-container">
    @* ── Left Sidebar ── *@
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Category</h4>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@(selectedCategories.Contains(cat))"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        @cat
                    </label>
                }
            }
            else
            {
                <p class="text-muted">Loading categories…</p>
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <label>
                Min
                <input type="number" step="0.01" min="0" @bind="filterMinPrice" />
            </label>
            <label>
                Max
                <input type="number" step="0.01" min="0" @bind="filterMaxPrice" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="filterInStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
