    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>⚠️ @errorMessage</p>
                <button class="btn btn-secondary" @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products…</p>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" @onchange="OnSortChanged">
                        @foreach (var opt in sortOptions)
                        {
                            <option value="@opt.Value" selected="@(currentSort == opt.Value)">@opt.Label</option>
                        }
                    </select>
                </div>
                <span class="showing-label">
                    Showing @((result.Page - 1) * result.PageSize + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount))
                    of @result.TotalCount products
                </span>
