                    <ProductCard Product="product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            @{ var totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize); }
            @if (totalPages > 1)
            {
                <nav class="pagination">
                    <button class="btn btn-page" disabled="@(currentPage <= 1)" @onclick="() => GoToPage(currentPage - 1)">
                        Previous
                    </button>
                    @for (var p = 1; p <= totalPages; p++)
                    {
                        var pageNum = p;
                        <button class="btn btn-page @(pageNum == currentPage ? "active" : "")"
                                @onclick="() => GoToPage(pageNum)">
                            @pageNum
                        </button>
                    }
                    <button class="btn btn-page" disabled="@(currentPage >= totalPages)" @onclick="() => GoToPage(currentPage + 1)">
                        Next
                    </button>
