@code {
    // ── Event for parent notification ──
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    // ── State ──
    private List<string>? categories;
    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    // Filter state
    private HashSet<string> selectedCategories = new();
    private decimal? filterMinPrice;
    private decimal? filterMaxPrice;
    private bool filterInStockOnly;

    // Active filter (sent to service)
    private ProductFilter activeFilter = new(null, null, null, false);

    // Sort & paging
    private string currentSort = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private readonly record struct SortOption(string Value, string Label);
    private static readonly SortOption[] sortOptions =
    [
        new("price_asc",  "Price: Low to High"),
        new("price_desc", "Price: High to Low"),
        new("name_asc",   "Name: A-Z"),
        new("rating_desc","Rating: Highest"),
    ];

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(activeFilter, currentSort, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = categoriesTask.Result;
            result = productsTask.Result;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    // ── Filter actions ──
    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        activeFilter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: filterMinPrice,
            MaxPrice: filterMaxPrice,
            InStockOnly: filterInStockOnly
        );
        currentPage = 1;
        await SearchAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        filterMinPrice = null;
        filterMaxPrice = null;
        filterInStockOnly = false;
        activeFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await SearchAsync();
    }

    // ── Sort ──
    private async Task OnSortChanged(ChangeEventArgs e)
    {
        currentSort = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchAsync();
    }

    // ── Pagination ──
    private async Task GoToPage(int page)
    {
        currentPage = page;
        await SearchAsync();
    }

    // ── Search helper ──
    private async Task SearchAsync()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            result = await ProductService.SearchAsync(activeFilter, currentSort, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Search failed: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task RetryLoad()
    {
        if (categories is null)
            await LoadInitialDataAsync();
        else
            await SearchAsync();
    }

    // ── Card callbacks ──
    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Hook for cart logic — no-op for now
        return Task.CompletedTask;
    }
}

