@page "/catalog"
@using sv_b0a32cdef2974757a41a7b12f291b7c2.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-container">
    @* ── Left Sidebar ── *@
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h4>Category</h4>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@(selectedCategories.Contains(cat))"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        @cat
                    </label>
                }
            }
            else
            {
                <p class="text-muted">Loading categories…</p>
            }
        </div>

        <div class="filter-section">
            <h4>Price Range</h4>
            <label>
                Min
                <input type="number" step="0.01" min="0" @bind="filterMinPrice" />
            </label>
            <label>
                Max
                <input type="number" step="0.01" min="0" @bind="filterMaxPrice" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="filterInStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ── Main Content ── *@
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>⚠️ @errorMessage</p>
                <button class="btn btn-secondary" @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products…</p>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" @onchange="OnSortChanged">
                        @foreach (var opt in sortOptions)
                        {
                            <option value="@opt.Value" selected="@(currentSort == opt.Value)">@opt.Label</option>
                        }
                    </select>
                </div>
                <span class="showing-label">
                    Showing @((result.Page - 1) * result.PageSize + 1)–@(Math.Min(result.Page * result.PageSize, result.TotalCount))
                    of @result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            @{ var totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize); }
            @if (totalPages > 1)
            {
                <nav class="pagination">
                    <button class="btn btn-page" disabled="@(currentPage <= 1)" @onclick="() => GoToPage(currentPage - 1)">
                        Previous
                    </button>
                    @for (var p = 1; p <= totalPages; p++)
                    {
                        var pageNum = p;
                        <button class="btn btn-page @(pageNum == currentPage ? "active" : "")"
                                @onclick="() => GoToPage(pageNum)">
                            @pageNum
                        </button>
                    }
                    <button class="btn btn-page" disabled="@(currentPage >= totalPages)" @onclick="() => GoToPage(currentPage + 1)">
                        Next
                    </button>
                </nav>
            }
        }
    </main>
</div>

